    'Back Bay King Bed Frame': 231,
    'Back Bay Accent Chair': 359,
    'Back Bay Bookcase': 344,
    'Back Bay Brass End Table': 16,
    'Back Bay Desk Chair': 293
}

# Get current year data for each location
# New York - 2030 data
ny_current = {}
for name, fid in target_products.items():
    subset = ny_df[ny_df['item_code'] == fid]
    if len(subset) > 0:
        ny_current[name] = subset['units_sold'].values[0]

# Chicago - 2028 data (but we have 2030 feedback)
chi_current = {}
for name, fid in target_products.items():
    subset = chi_df[chi_df['furniture_id'] == fid]
    if len(subset) > 0:
        chi_current[name] = subset['items_sold'].values[0]

# San Francisco - 2029 data (but we have 2030 feedback)
sf_current = {}
for name, fid in target_products.items():
    subset = sf_df[sf_df['product_id'] == fid]
    if len(subset) > 0:
        sf_current[name] = subset['quantity'].values[0]

