print("\nNew York (2030 data):")
for name in target_products:
    if name in ny_current:
        print(f"  {name}: current={ny_current[name]}, feedback_2030={feedback_2030['New York'][name]}")
    else:
        print(f"  {name}: NOT IN DATA, feedback_2030={feedback_2030['New York'][name]}")

print("\nChicago (2028 data):")
for name in target_products:
    if name in chi_current:
        print(f"  {name}: current={chi_current[name]}, feedback_2030={feedback_2030['Chicago'][name]}")
    else:
        print(f"  {name}: NOT IN DATA, feedback_2030={feedback_2030['Chicago'][name]}")

print("\nSan Francisco (2029 data):")
for name in target_products:
    if name in sf_current:
        print(f"  {name}: current={sf_current[name]}, feedback_2030={feedback_2030['San Francisco'][name]}")
    else:
        print(f"  {name}: NOT IN DATA, feedback_2030={feedback_2030['San Francisco'][name]}")

# Calculate growth rates from available data to 2030
print("\n=== Growth Analysis ===")
# For products with historical data, calculate growth to 2030
for loc in ['Chicago', 'San Francisco', 'New York']:
    print(f"\n{loc}:")
    for name in target_products:
        fb_val = feedback_2030[loc][name]
        if loc == 'New York' and name in ny_current:
            hist_val = ny_current[name]
            if hist_val > 0:
                growth = (fb_val - hist_val) / hist_val
                print(f"  {name}: {hist_val} -> {fb_val}, growth={growth:.2%}")
        elif loc == 'Chicago' and name in chi_current:
            hist_val = chi_current[name]
            if hist_val > 0:
                # 2028 to 2030 = 2 years
                growth_2yr = (fb_val - hist_val) / hist_val
                annual_growth = (1 + growth_2yr)**0.5 - 1
                print(f"  {name}: {hist_val} (2028) -> {fb_val} (2030), 2yr growth={growth_2yr:.2%}, annual={annual_growth:.2%}")
        elif loc == 'San Francisco' and name in sf_current:
            hist_val = sf_current[name]
            if hist_val > 0:
                # 2029 to 2030 = 1 year
                growth = (fb_val - hist_val) / hist_val
                print(f"  {name}: {hist_val} (2029) -> {fb_val} (2030), growth={growth:.2%}")

# Build predictions using growth rates
# Use 2030 as base and apply growth rates
print("\n=== Predictions for 2031-2035 ===")
predictions = {}

# Calculate average growth rates by product type across locations
# Use the growth from historical data to 2030 as the growth rate
for loc in ['Chicago', 'San Francisco', 'New York']:
    for name in target_products:
        base = feedback_2030[loc][name]

        # Calculate growth rate based on available data
        growth_rate = 0.05  # default 5% growth

        if loc == 'New York' and name in ny_current and ny_current[name] > 0:
            growth_rate = (base - ny_current[name]) / ny_current[name]
        elif loc == 'Chicago' and name in chi_current and chi_current[name] > 0:
            growth_2yr = (base - chi_current[name]) / chi_current[name]
            growth_rate = (1 + growth_2yr)**0.5 - 1
        elif loc == 'San Francisco' and name in sf_current and sf_current[name] > 0:
            growth_rate = (base - sf_current[name]) / sf_current[name]

        # Cap growth rate to reasonable bounds
        growth_rate = max(-0.1, min(0.2, growth_rate))

        print(f"\n{loc} / {name}: base={base}, growth_rate={growth_rate:.2%}")
        for year in range(2031, 2036):
            years_ahead = year - 2030
            pred = base * ((1 + growth_rate) ** years_ahead)
            pred = round(pred)
            predictions[(loc, name, year)] = pred
            print(f"  {year}: {pred}")

# Save predictions
with open('/app/predictions.json', 'w') as f:
    json.dump(predictions, f, indent=2)

print("\nPredictions saved to /app/predictions.json")
